extends SceneTree

const W := 400
const H := 300

func _initialize() -> void:
	_run()

func _vp() -> SubViewport:
	var vp := SubViewport.new()
	vp.size = Vector2i(W, H)
	vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	root.add_child(vp)
	var cm := CanvasModulate.new()
	cm.color = Color(0, 0, 0, 1)
	vp.add_child(cm)
	var fr := ColorRect.new()
	fr.color = Color(1, 1, 1, 1)
	fr.size = Vector2(W, H)
	vp.add_child(fr)
	return vp

func _wh_tex(n: int) -> ImageTexture:
	var img := Image.create(n, n, false, Image.FORMAT_RGBA8)
	img.fill(Color(1, 1, 1, 1))
	return ImageTexture.create_from_image(img)

func _frames(n: int) -> void:
	for i in n:
		await process_frame

func _bbox(img: Image) -> String:
	var x0 := 9999; var y0 := 9999; var x1 := -1; var y1 := -1
	for y in range(H):
		for x in range(W):
			if img.get_pixel(x, y).r > 0.5:
				x0 = mini(x0, x); y0 = mini(y0, y); x1 = maxi(x1, x); y1 = maxi(y1, y)
	return "lit bbox x[%d..%d] y[%d..%d]" % [x0, x1, y0, y1]

func _poly_node(vp: SubViewport, x0: int, y0: int, x1: int, y1: int, cull: int = OccluderPolygon2D.CULL_DISABLED) -> void:
	var occ := LightOccluder2D.new()
	var op := OccluderPolygon2D.new()
	op.polygon = PackedVector2Array([Vector2(x0, y0), Vector2(x1, y0), Vector2(x1, y1), Vector2(x0, y1)])
	op.cull_mode = cull
	occ.occluder = op
	vp.add_child(occ)

# integer closed-box segment test in doubled coordinates (EM-20 a). rects half-open [x0,x1)x[y0,y1)
func _blocked(fx: int, fy: int, sx: int, sy: int, rects: Array) -> bool:
	var ax := 2 * fx; var ay := 2 * fy; var bx := 2 * sx; var by := 2 * sy
	for r in rects:
		var bx0: int = 2 * r[0] - 1; var by0: int = 2 * r[1] - 1; var bx1: int = 2 * r[2] - 1; var by1: int = 2 * r[3] - 1
		if maxi(ax, bx) < bx0 or mini(ax, bx) > bx1 or maxi(ay, by) < by0 or mini(ay, by) > by1:
			continue
		var dx := bx - ax; var dy := by - ay
		var pos := 0; var neg := 0
		for c in [[bx0, by0], [bx1, by0], [bx0, by1], [bx1, by1]]:
			var cr: int = dx * (c[1] - ay) - dy * (c[0] - ax)
			if cr > 0: pos += 1
			elif cr < 0: neg += 1
		if pos == 4 or neg == 4:
			continue
		return true
	return false

func _inside(x: int, y: int, rects: Array) -> bool:
	for r in rects:
		if x >= r[0] and x < r[2] and y >= r[1] and y < r[3]:
			return true
	return false

func _run() -> void:
	# A: offset frame and texture apex
	for rot in [0.0, PI / 2.0]:
		var vp := _vp()
		var l := PointLight2D.new()
		l.texture = _wh_tex(100)
		l.position = Vector2(200, 150)
		l.rotation = rot
		l.offset = Vector2(0, -60)
		l.shadow_enabled = false
		vp.add_child(l)
		await _frames(4)
		print("A rot=%.2f node=(200,150) off=(0,-60): %s  (local-frame centre predicts (200+60*sin..)): rot0 -> centre (200,90); rot90 local -> (260,150), world-fixed -> (200,90)" % [rot, _bbox(vp.get_texture().get_image())])
		vp.queue_free()
	# A2: texture_scale 2 with offset: is offset scaled?
	var vp2 := _vp()
	var l2 := PointLight2D.new()
	l2.texture = _wh_tex(100)
	l2.texture_scale = 2.0
	l2.position = Vector2(200, 150)
	l2.offset = Vector2(0, -60)
	l2.shadow_enabled = false
	vp2.add_child(l2)
	await _frames(4)
	print("A2 scale=2 off=(0,-60): ", _bbox(vp2.get_texture().get_image()), " (centre (200,90) -> bbox y[-10..190] clipped to 0..189 if unscaled; scaled offset would centre y=30)")
	vp2.queue_free()
	# B: light inside closed polygon by cull mode
	for cull in [OccluderPolygon2D.CULL_DISABLED, OccluderPolygon2D.CULL_CLOCKWISE, OccluderPolygon2D.CULL_COUNTER_CLOCKWISE]:
		var vp := _vp()
		_poly_node(vp, 200, 145, 208, 155, cull)
		_poly_node(vp, 300, 100, 308, 200, cull)
		var l := PointLight2D.new()
		l.texture = _wh_tex(1200)
		l.position = Vector2(204, 150)
		l.shadow_enabled = true
		vp.add_child(l)
		await _frames(4)
		var img := vp.get_texture().get_image()
		print("B cull=%d light inside block: lum W(150,150)=%.2f N(204,100)=%.2f E(260,150)=%.2f beyond-wall(340,150)=%.2f" % [cull, img.get_pixel(150,150).r, img.get_pixel(204,100).r, img.get_pixel(260,150).r, img.get_pixel(340,150).r])
		vp.queue_free()
	# C: lattice test against the sim closed-box segment test
	var rects := [[230, 100, 262, 124], [150, 180, 220, 204], [300, 40, 324, 140], [250, 190, 274, 214]]
	for F in [Vector2i(190, 130), Vector2i(215, 160), Vector2i(205, 108)]:
		for shift in [Vector2(0, 0), Vector2(0.5, 0.5), Vector2(-0.5, -0.5), Vector2(0.5, 0)]:
			var vp := _vp()
			for r in rects:
				_poly_node(vp, r[0], r[1], r[2], r[3])
			var l := PointLight2D.new()
			l.texture = _wh_tex(1200)
			l.position = Vector2(F) + shift
			l.shadow_enabled = true
			l.shadow_filter = Light2D.SHADOW_FILTER_NONE
			vp.add_child(l)
			await _frames(4)
			var img := vp.get_texture().get_image()
			var n := 0; var mism := 0; var lit_dark := 0; var dark_lit := 0
			for y in range(10, 290):
				for x in range(10, 390):
					if _inside(x, y, rects) or (x == F.x and y == F.y):
						continue
					var sim_blocked := _blocked(F.x, F.y, x, y, rects)
					var drawn_lit: bool = img.get_pixel(x, y).r > 0.5
					n += 1
					if sim_blocked == drawn_lit:
						mism += 1
						if drawn_lit: dark_lit += 1   # sim blocked, drawn lit (light leaks)
						else: lit_dark += 1           # sim open, drawn dark
			print("C F=", F, " shift=", shift, " cells=%d mismatches=%d (sim-blocked drawn-lit %d, sim-open drawn-dark %d)" % [n, mism, dark_lit, lit_dark])
			vp.queue_free()
	quit()
EOF
